it.each(['pending', 'unknown'] as const)(
  'continues the original v4 Supervisor accepted-result Action after compact definitions ship (%s)',
  async (status) => {
    const original = JSON.parse(
      await fs.readFile('test/fixtures/native-v4-internal-actions/workflow.json', 'utf8'),
    );
    const application = nativeSdkApplicationForRun({
      workflow: {
        id: 'comet-native',
        version: '4',
        hash: hashRuntimeValue(defineWorkflow(original)),
      },
    });
    const f = await integratedAgentSupervisorFixture(false, application);
    let run = f.run;
    const state = run.state as NativePortableState;
    run = await succeedLatestAction(
      f.runtime,
      run,
      {
        candidateId: state.builder_handoff!.candidate_id,
        verifierExecutionRef: 'parent-agent',
        checks: [],
        response: {
          kind: 'final-result',
          result: {
            iteration: state.loop.iteration,
            attempt: state.loop.attempt,
            verdict: 'pass',
            acceptance: [
              {
                id: 'A1',
                result: 'passed',
                reason: 'Both integrated child outputs were observed.',
              },
            ],
            risks: [],
            summary: 'The complete parent requirement passed.',
          },
        },
      },
      f.root,
      'original-parent-verified',
      'parent-agent',
    );
    const wait = run.waits.at(-1)!;
    expect(wait.stepId).toBe('verify.confirm');
    run = await f.runtime.resolveWait({
      runId: run.runId,
      waitId: wait.id,
      proposalHash: wait.proposalHash,
      decisionId: 'fixture-original-result-approved',
      choice: 'approved',
    });
    const action = run.actions.at(-1)!;
    expect(action.stepId).toBe('verify.revalidate');
    const context = { requestId: 'restore-original-parent-result', projectRoot: f.root };
    if (status === 'unknown') {
      run = await f.runtime.claim({
        runId: run.runId,
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        executorId: 'comet-native-report-revalidate',
        claimToken: 'original-result-read',
        context,
      });
      run = await f.runtime.markUnknown({
        runId: run.runId,
        actionId: action.id,
        attempt: action.attempt,
        reason: 'The original process stopped before publishing its read-only result.',
      });
    }
    const selected = nativeSdkApplicationForRun(run);
    const restored = createRuntime({
      ...selected,
      store: f.store,
      workflows: [selected.workflow],
      transitionHandlers: [selected.transitionHandler],
    });
    let resumed =
      status === 'unknown'
        ? await recoverNativeSdkReportRevalidation(f.root, run, restored)
        : await restored.execute({
            runId: run.runId,
            actionId: action.id,
            executorId: 'comet-native-report-revalidate',
            context,
          });
    expect(resumed.workflow).toEqual(run.workflow);
    expect(resumed.runId).toBe(run.runId);
    expect(resumed.waits).toEqual(run.waits);
    expect(resumed.actions.slice(0, -2)).toEqual(run.actions.slice(0, -1));
    expect(resumed.actions.find((a) => a.id === action.id)).toMatchObject({
      id: action.id,
      inputHash: action.inputHash,
      status: 'succeeded',
    });
    expect(resumed.actions.at(-1)?.stepId).toBe('supervisor.parent.deliver');
    expect(resumed.actions.filter((a) => a.stepId === 'supervisor.parent.deliver')).toHaveLength(1);
    const repeated = await recoverNativeSdkReportRevalidation(f.root, resumed, restored);
    expect(repeated).toEqual(resumed);
    resumed = await restored.execute({
      runId: resumed.runId,
      actionId: resumed.actions.at(-1)!.id,
      executorId: 'native-supervisor-parent-deliver',
      context,
    });
    expect(resumed.actions.find((a) => a.stepId === 'supervisor.parent.deliver')?.status).toBe(
      'succeeded',
    );
    expect((await fs.readFile(path.join(f.root, 'api.txt'), 'utf8')).trim()).toBe(
      'API implemented',
    );
    expect((await fs.readFile(path.join(f.root, 'ui.txt'), 'utf8')).trim()).toBe('UI implemented');
  },
  120_000,
);
